                let h = rd(oc as usize + 0x44);
                let tt = [4u32, h, 0, loc.as_ptr() as u32, n as u32, q(rd(r + 0xC)), 0];
                let o = vc(a, 13, &[tt.as_ptr() as u32]);
                call_regs(0x00B3_B640, 0, o, 0, 0, 0, &[tt.as_ptr() as u32]);
