                wd(t + n * 4 + 0xB8, rd(o as usize + 0x44));
                let n = rd(t + 0x204) as usize;
                wd(t + n * 4 + 0x158, 0);
                let n = rd(t + 0x204) as usize;
                wd(t + n * 4 + 0x108, 0xFFFF_FFFF);
                let n = rd(t + 0x204) as usize;
                wd(t + n * 4 + 0x1A8, 1);
                wd(t + 0x204, rd(t + 0x204).wrapping_add(1));
