unsafe fn gas_step(this: u32) {
    unsafe {
        GAS_CALLS.fetch_add(1, Ordering::Relaxed);
        let t = this as usize;
        let sect = |idx: u32| this.wrapping_add(idx.wrapping_mul(0x1D4));
        if (rd(sect(rd(t + 0x30F8)) as usize + 0x494) as i32) > 0 {
            let mut k: i32 = 0;
            loop {
                let base = sect(rd(t + 0x30F8));
                let rec = base.wrapping_add((k as u32).wrapping_mul(20)).wrapping_add(0x340);
                let state = rd(rec as usize);
                if state <= 0x2F {
                    GAS_STATE_HITS[state as usize].fetch_add(1, Ordering::Relaxed);
                    gas_state(this, base, rec, state);
                }
                k += 1;
                if k >= rd(sect(rd(t + 0x30F8)) as usize + 0x494) as i32 {
                    break;
                }
            }
        }
        // The second list: every entry equal to 1 re-arms the shared object.
        if (rd(sect(rd(t + 0x30F8)) as usize + 0x510) as i32) > 0 {
            let obj = rd(0x0252_7558) as usize;
            let mut off = 0x498u32;
            let mut j = 0i32;
            loop {
                if rd(sect(rd(t + 0x30F8)).wrapping_add(off) as usize) == 1 {
                    wb(obj + 0x2C, 0);
                    wb(obj + 0x1C, 1);
                }
                j += 1;
                off += 0x18;
                if j >= rd(sect(rd(t + 0x30F8)) as usize + 0x510) as i32 {
                    break;
                }
            }
        }
        let now = rd(GAME_NOW);
        wd(t + 0x30FC, now);
        if (now as i32) > 0x6B49_D200 {
            wd(t + 0x30FC, now.wrapping_add(0x94B6_2E00));
        }
    }
}

extern "stdcall" fn gas_step_entry(this: u32) {
    unsafe { gas_step(this) }
}

